effect.frag.content:
uniform float u_wear;
uniform float u_jitter;
uniform float u_scratches;
const float TAU = 6.28318530718;
uint hash(uint x) { x ^= x >> 16; x *= 2146121005u; x ^= x >> 15; x *= 2221713035u; return x ^ (x >> 16); }
float randomValue(uint i) { return float(hash(i + hash(uint(u_seed))) >> 8) / 16777216.0; }
vec4 sourceAt(vec2 uv) {
  if (any(lessThan(uv, vec2(0.0))) || any(greaterThan(uv, vec2(1.0)))) return vec4(0.0);
  return texture(u_source, uv);
}
void main() {
  vec2 aspect = u_resolution / min(u_resolution.x, u_resolution.y);
  float phase = TAU * u_progress;
  vec2 shake = vec2(sin(phase * 13.0) + 0.4 * sin(phase * 23.0), cos(phase * 17.0) + 0.4 * sin(phase * 29.0));
  vec4 c = sourceAt(v_uv + shake * u_jitter / aspect);
  float luminance = dot(c.rgb, vec3(0.2126, 0.7152, 0.0722));
  c.rgb = mix(c.rgb, min(vec3(c.a), luminance * vec3(1.08, 0.98, 0.78)), u_wear * 0.85);
  uvec2 grainCell = uvec2(floor(v_uv * aspect * 256.0));
  uint grainId = grainCell.x + hash(grainCell.y);
  float frame = u_progress * 24.0;
  uint tick = uint(floor(frame));
  float grain = mix(randomValue(grainId + tick * 65537u), randomValue(grainId + ((tick + 1u) % 24u) * 65537u), smoothstep(0.0, 1.0, fract(frame))) - 0.5;
  float exposure = 1.0 - u_wear * (0.04 + 0.04 * sin(phase * 11.0));
  c.rgb = c.rgb * exposure + grain * c.a * u_wear * 0.18;
  float damage = 0.0;
  for (int i = 0; i < 12; i++) {
    if (float(i) >= u_scratches) break;
    float id = float(i);
    float x = randomValue(uint(i) + 100u) + sin(phase + id) * 0.025 / aspect.x;
    float line = 1.0 - smoothstep(0.0005, 0.0018, abs(v_uv.x - x) * aspect.x);
    damage += line * (0.35 + 0.25 * sin(phase * 3.0 + id));
  }
  vec2 dustGrid = v_uv * aspect * 18.0;
  uvec2 dustCell = uvec2(floor(dustGrid));
  float dust = step(0.94, randomValue(dustCell.x + hash(dustCell.y))) *
    (1.0 - smoothstep(0.03, 0.12, length(fract(dustGrid) - 0.5))) * (0.5 + 0.5 * sin(phase * 5.0));
  c.rgb *= 1.0 - dust * u_wear * 0.65;
  c.rgb = mix(c.rgb, vec3(c.a), clamp(damage, 0.0, 0.8));
  fragColor = vec4(clamp(c.rgb, vec3(0.0), vec3(c.a)), c.a);
}
